1	import React, { useState, useEffect } from 'react';
2	import { Link, useParams } from 'react-router-dom';
3	import { FiChevronLeft, FiChevronRight } from 'react-icons/fi';
4	
5	import api from '../../services/api';
6	
7	import logoImage from '../../assets/logo.svg';
8	import Footer from '../../components/Footer';
9	
10	import { Header, RespositoryInfo, Issues } from './styles';
11	
12	interface Repository {
13	  full_name: string;
14	  description: string;
15	  owner: {
16	    login: string;
17	    avatar_url: string;
18	  };
19	  stargazers_count: number;
20	  forks_count: number;
21	  open_issues_count: number;
22	}
23	interface Issue {
24	  id: number;
25	  title: string;
26	  html_url: string;
27	  user: {
28	    login: string;
29	  };
30	}
31	
32	const Repository: React.FC = () => {
33	  const { '*': repositoryName } = useParams();
34	  const [repository, setRepository] = useState<Repository | null>(null);
35	  const [issues, setIssues] = useState<Issue[]>([]);
36	  const [page, setPage] = useState(1);
37	  const [hasMore, setHasMore] = useState(true);
38	  const [loading, setLoading] = useState(false);
39	
40	  const loadIssues = (pageNum: number) => {
41	    setLoading(true);
42	    api
43	      .get(`/repos/${repositoryName}/issues`, {
44	        params: { page: pageNum, per_page: 30 },
45	      })
46	      .then((response) => {
47	        if (response.data.length === 0) {
48	          setHasMore(false);
49	        } else if (response.data.length < 30) {
50	          setIssues((prev) => [...prev, ...response.data]);
51	          setHasMore(false);
52	        } else {
53	          setIssues((prev) => [...prev, ...response.data]);
54	        }
55	        setPage(pageNum);
56	        setLoading(false);
57	      });
58	  };
59	
60	  const handleLoadMore = () => {
61	    loadIssues(page + 1);
62	  };
63	
64	  useEffect(() => {
65	    api.get(`/repos/${repositoryName}`).then((response) => {
66	      setRepository(response.data);
67	    });
68	    loadIssues(1);
69	  }, [repositoryName]);
70	
71	  return (
72	    <>
73	      <Header>
74	        <img src={logoImage} alt="Github Explorer" />
75	        <Link to="/">
76	          <FiChevronLeft size={16} color="#3D3D4D" />
77	          <strong>Voltar</strong>
78	        </Link>
79	      </Header>
80	      {repository ? (
81	        <RespositoryInfo>
82	          <header>
83	            <img src={repository.owner.avatar_url} alt="Owner profile avatar" />
84	            <div>
85	              <strong>{repository.full_name}</strong>
86	              <p>{repository.description}</p>
87	            </div>
88	          </header>
89	          <ul>
90	            <li>
91	              <strong>{repository.stargazers_count}</strong>
92	              <span>Stars</span>
93	            </li>
94	            <li>
95	              <strong>{repository.forks_count}</strong>
96	              <span>Forks</span>
97	            </li>
98	            <li>
99	              <strong>{repository.open_issues_count}</strong>
100	              <span>Issues abertos</span>
101	            </li>
102	          </ul>
103	        </RespositoryInfo>
104	      ) : (
105	        <p>Carregando informações.</p>
106	      )}
107	
108	      <Issues>
109	        {issues.map((issue) => (
110	          <a key={issue.id} href={issue.html_url}>
111	            <div>
112	              <strong>{issue.title}</strong>
113	              <p>{issue.user.login}</p>
114	            </div>
115	            <FiChevronRight size={20} />
116	          </a>
117	        ))}
118	        {hasMore && (
119	          <button
120	            onClick={handleLoadMore}
121	            disabled={loading}
122	            className="load-more-btn"
123	          >
124	            {loading ? 'Carregando...' : 'Carregar mais'}
125	          </button>
126	        )}
127	      </Issues>
128	
129	      <Footer />
130	    </>
131	  );
132	};
133	
134	export default Repository;
